def is_ludic(n):
    if n == 1:
        return True

    factors = []
    i = 2
    temp = n
    while i * i <= temp:
        if temp % i == 0:
            factors.append(i)
            while temp % i == 0:
                temp //= i
        i += 1
    if temp > 1:
        factors.append(temp)

    if not factors:
        return False

    product = 1
    for factor in factors:
        product *= factor

    if product == n:
        return True
    else:
        return False

