    if not nums:
        return 0

    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    nums.sort()
    max_size = 0
    for i in range(1 << len(nums)):
        subset = []
        for j in range(len(nums)):
            if (i >> j) & 1:
                subset.append(nums[j])

        if not subset:
            continue

        is_divisible = True
        for k in range(len(subset)):
            for l in range(k + 1, len(subset)):
                if subset[l] % subset[k] != 0:
