def is_polite(n):
    """
    A polite number is a number that can be written as the sum of two squares.
    For example, 25 is a polite number because 25 = 5^2 + 0^2.
    Also, 50 is a polite number because 50 = 5^2 + 5^2.
    """
    if n <= 0:
        return 0
    count = 0
    num = 1
    while count < n:
        is_sum_of_two_squares = False
        for i in range(int(num**0.5) + 1):
            j_squared = num - i**2
            if j_squared >= 0:
                j = int(j_squared**0.5)
                if j**2 == j_squared:
                    is_sum_of_two_squares = True
                    break
        if is_sum_of_two_squares:
            count += 1
        if count == n:
            return num
        num += 1
    return 0

